    'd50_spec_range_μm': {
      min: parseFloat(data.quality_data?.['d50_spec_min_μm'] || data.lot_info['d50_spec_min_μm']) || 10,
      max: parseFloat(data.quality_data?.['d50_spec_max_μm'] || data.lot_info['d50_spec_max_μm']) || 15
    },
